// Build Kubernetes Job manifest
const jobName = $input.item.json.jobName;
const namespace = $input.item.json.namespace;
const image = $input.item.json.image;
const command = JSON.parse($input.item.json.command);

// Sanitize job name for Kubernetes (lowercase, alphanumeric and hyphens only, max 63 chars)
let sanitizedName = jobName.toLowerCase()
  .replace(/[^a-z0-9-]/g, '-')
  .replace(/^-+|-+$/g, '')
  .substring(0, 63);
// Ensure it doesn't start or end with hyphen
if (sanitizedName.endsWith('-')) {
  sanitizedName = sanitizedName.slice(0, -1);
}
if (sanitizedName.startsWith('-')) {
  sanitizedName = sanitizedName.substring(1);
}
// Ensure it's not empty
if (!sanitizedName) {
  sanitizedName = 'n8n-job-' + Date.now();
}

const jobManifest = {
  apiVersion: 'batch/v1',
  kind: 'Job',
  metadata: {
    name: sanitizedName,
    namespace: namespace,
    labels: {
      'created-by': 'n8n',
      'workflow': 'kubernetes-job-creator'
    }
  },
  spec: {
    ttlSecondsAfterFinished: 300,
    backoffLimit: 3,
    template: {
      spec: {
        restartPolicy: 'Never',
        containers: [
          {
            name: 'job-container',
            image: image,
            command: command,
            resources: {
              requests: {
                memory: '64Mi',
                cpu: '100m'
              },
              limits: {
                memory: '128Mi',
                cpu: '200m'
              }
            }
          }
        ]
      }
    }
  }
};

return {
  json: {
    jobManifest: jobManifest,
    jobName: sanitizedName,
    namespace: namespace,
    image: image,
    command: command
  }
};

// Get Kubernetes API configuration
// Using service account token for authentication
// IMPORTANT: Replace K8S_SERVICE_ACCOUNT_TOKEN_PLACEHOLDER with your actual service account token
// You can get the token using: kubectl create token <service-account-name> -n <namespace>
const token = 'K8S_SERVICE_ACCOUNT_TOKEN_PLACEHOLDER';
// IMPORTANT: Replace K8S_API_SERVER_PLACEHOLDER with your Kubernetes API server URL
// Example: 'https://192.168.122.100:6443' or get it with: kubectl cluster-info
const apiServer = 'K8S_API_SERVER_PLACEHOLDER';

return {
  json: {
    ...$input.item.json,
    k8sToken: token,
    k8sApiServer: apiServer
  }
};
